using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "NegativeFieldEffect", menuName = "Data/Battle/Effects/Hevelius/NegativeField Effect")]
public class NegativeFieldEffect : Effect
{
	[Header("Negative Field Effect")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public bool RedirectCorruption(UnitEffects unitEffects, int corruptAmount, GameObject source)
	{
		if (currentCompanions.ActiveCompanions.Count == 0)
		{
			return false;
		}
		List<CorruptionStats> list = new List<CorruptionStats>();
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			CorruptionStats component = currentCompanions.ActiveCompanions[i].GetComponent<CorruptionStats>();
			if (!component.IsDefeated())
			{
				list.Add(component);
			}
		}
		if (list.Count == 0)
		{
			return false;
		}
		unitEffects.IsEffectActive(this);
		list.PickRandom().Corrupt(corruptAmount, source);
		return true;
	}
}
